const {chromium}=require('playwright');const out={http5xx:[],pageErrors:[],viewportResults:[],api:{}};(async()=>{const b=await chromium.launch({headless:true,executablePath:'/ms-playwright/chromium-1187/chrome-linux/chrome',args:['--no-sandbox']});const c=await b.newContext({locale:'ar-SA'});const p=await c.newPage();p.on('pageerror',e=>out.pageErrors.push(e.message));p.on('console',m=>{if(m.type()==='error'&&!/status of 401|status of 404/.test(m.text()))out.pageErrors.push(m.text())});p.on('response',r=>{if(r.status()>=500)out.http5xx.push(`${r.status()} ${r.url()}`)});await p.route('https://tile.openstreetmap.org/**',r=>r.fulfill({status:200,contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/pN8AAAAASUVORK5CYII=','base64')}));const base='http://host.docker.internal:8080';await p.goto(`${base}/?view=data-dashboard`,{waitUntil:'domcontentloaded'});await p.waitForFunction(()=>document.querySelector('#rdOpportunityMap')&&document.querySelector('#dashRegionFilter'),null,{timeout:15000});const catalog=await p.evaluate(async()=>{const r=await fetch('/api/geography/catalog');return {status:r.status,data:await r.json()}});if(catalog.status!==200||!catalog.data.national_ui_enabled||!catalog.data.national_dashboard_enabled||!catalog.data.national_map_enabled)throw Error('Live geography catalog flags are not all enabled');const apis=await p.evaluate(async()=>{const [s,m]=await Promise.all([fetch('/api/data-dashboard/geography-summary'),fetch('/api/data-dashboard/geography')]);return {summary:{status:s.status,body:await s.json()},map:{status:m.status,body:await m.json()}}});out.api={summaryStatus:apis.summary.status,summaryMasters:apis.summary.body.unique_master_total,mappedMasters:apis.summary.body.mapped_unique_masters,summaryBytes:new TextEncoder().encode(JSON.stringify(apis.summary.body)).length,mapStatus:apis.map.status,mapMasters:apis.map.body.counts.total,mapExact:apis.map.body.counts.exact_mapped,mapOutside:apis.map.body.counts.outside_boundary,mapPoints:apis.map.body.points.length,mapBytes:new TextEncoder().encode(JSON.stringify(apis.map.body)).length};if(apis.summary.status!==200||apis.map.status!==200||out.api.summaryMasters!==6657||out.api.mappedMasters!==5889||out.api.mapMasters!==6657||out.api.mapExact!==5889||out.api.mapOutside!==0)throw Error(`Live summary/map contract mismatch ${JSON.stringify(out.api)}`);await p.locator('#rdFilterPanel').evaluate(e=>e.open=true);const regionWait=p.waitForResponse(r=>{const u=new URL(r.url());return u.pathname==='/api/data-dashboard/geography'&&u.searchParams.get('region_id')==='5'},{timeout:60000});await p.locator('#dashRegionFilter').selectOption('5');const regionResponse=await regionWait;if(regionResponse.status()!==200)throw Error(`Region map HTTP ${regionResponse.status()}`);await p.waitForFunction(()=>!document.querySelector('#dashGovernorateFilter').disabled,null,{timeout:5000});const govWait=p.waitForResponse(r=>{const u=new URL(r.url());return u.pathname==='/api/data-dashboard/geography'&&u.searchParams.get('governorate_id')==='501'},{timeout:60000});await p.locator('#dashGovernorateFilter').selectOption('501');const govResponse=await govWait;if(govResponse.status()!==200||!new URL(p.url()).searchParams.has('governorate_id'))throw Error('Governorate filter failed to propagate');const sourceWait=p.waitForResponse(r=>{const u=new URL(r.url());return u.pathname==='/api/data-dashboard/geography'&&u.searchParams.get('source')==='ncp'},{timeout:60000});await p.locator('#dashSource').selectOption('ncp');const sourceResponse=await sourceWait;if(sourceResponse.status()!==200||!new URL(p.url()).searchParams.has('source'))throw Error('Source filter failed to propagate');await p.locator('#dashReset').click();await p.waitForTimeout(600);let popup=p.locator('#rdOpportunityMap [data-map-open]').first();for(let i=0;i<14&&await popup.count()===0;i++){const markers=p.locator('#rdOpportunityMap .leaflet-marker-icon');if(!await markers.count())break;await markers.last().click({force:true});await p.waitForTimeout(180);popup=p.locator('#rdOpportunityMap [data-map-open]').first()}if(!await popup.count())throw Error('No live map marker popup was available');const ids=await popup.getAttribute('data-map-open');const listWait=p.waitForResponse(r=>r.url().includes('/api/opportunities?')&&new URL(r.url()).searchParams.get('map_ids')===ids,{timeout:15000});await popup.click({force:true});const listResponse=await listWait;if(listResponse.status()!==200||!p.url().includes(`map_ids=${ids}`))throw Error('Marker-to-list drilldown failed');await p.waitForFunction(()=>document.querySelectorAll('#opportunityRows [data-detail]').length>0,null,{timeout:15000});await p.locator('#opportunityRows [data-detail]').first().click({force:true});await p.waitForFunction(()=>document.querySelector('#modal.show'),null,{timeout:10000});await p.locator('#modalClose').click({force:true});await p.goto(`${base}/?view=data-dashboard`,{waitUntil:'domcontentloaded'});await p.waitForTimeout(500);for(const [w,h] of [[1920,1080],[1440,900],[1366,768],[768,900],[390,844]]){await p.setViewportSize({width:w,height:h});await p.waitForTimeout(200);const f=await p.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,mapWidth:document.querySelector('#rdOpportunityMap')?.getBoundingClientRect().width||0,regionVisible:!!document.querySelector('#dashRegionFilter')?.getClientRects().length}));if(f.mapWidth<100||!f.regionVisible||f.scroll>f.width+1)throw Error(`Responsive layout ${w}x${h}: ${JSON.stringify(f)}`);out.viewportResults.push({viewport:`${w}x${h}`,status:'PASSED',...f})}await b.close();if(out.http5xx.length||out.pageErrors.length)throw Error(JSON.stringify(out));console.log(JSON.stringify(out));})().catch(e=>{console.error(e);process.exit(1)});